-- opencode installer for ComputerCraft.
--
-- Generated by install.lua. Re-run that after adding a module, and copy this
-- file to the computer again.
--
--   install                  the modular tree, into the current directory
--   install --bundle         dist/opencode.lua alone, as opencode.lua
--   install <url>            fetch from somewhere else
--
-- The base url is baked in when the repository is known. When it is not, pass
-- one: `install <url>` installs from a fork, a mirror, or a paste.

local BASE = ""

-- Otherwise the installer looks for the raw files itself, under this repository.
local REPO = "https://git.ld50.dev/lucretia/CC-opencode"
local BRANCH = "main"

-- CC-GUI, which the interface is built on. A separate project in a separate
-- repository, so it is fetched from there and not from this one: a checkout of this
-- project has no GUI.lua in it, and an installer that looked for one would be
-- looking for a file that is not there.
local GUI_REPO = "https://github.com/LD-Reborn/CC-GUI"
local GUI_BRANCH = "main"

-- Its path in that repository, and the size it has to come back at.
local GUI_PATH = "GUI.lua"
local GUI_SIZE = 18625

-- fetch path, expected size, path to write
local FILES = {
  { "init.lua", 25188, "init.lua" },
  { "src/agent.lua", 13912, "src/agent.lua" },
  { "src/config.lua", 6849, "src/config.lua" },
  { "src/environment.lua", 16849, "src/environment.lua" },
  { "src/http.lua", 9866, "src/http.lua" },
  { "src/json.lua", 9449, "src/json.lua" },
  { "src/llm.lua", 8315, "src/llm.lua" },
  { "src/pattern.lua", 13485, "src/pattern.lua" },
  { "src/permission.lua", 5649, "src/permission.lua" },
  { "src/prompt.lua", 7430, "src/prompt.lua" },
  { "src/provider.lua", 6448, "src/provider.lua" },
  { "src/session.lua", 7047, "src/session.lua" },
  { "src/tool/bash.lua", 8924, "src/tool/bash.lua" },
  { "src/tool/edit.lua", 9879, "src/tool/edit.lua" },
  { "src/tool/glob.lua", 2449, "src/tool/glob.lua" },
  { "src/tool/grep.lua", 4643, "src/tool/grep.lua" },
  { "src/tool/read.lua", 6948, "src/tool/read.lua" },
  { "src/tool/registry.lua", 4947, "src/tool/registry.lua" },
  { "src/tool/todowrite.lua", 4084, "src/tool/todowrite.lua" },
  { "src/tool/webfetch.lua", 3373, "src/tool/webfetch.lua" },
  { "src/tool/write.lua", 2421, "src/tool/write.lua" },
  { "src/truncate.lua", 3232, "src/truncate.lua" },
  { "src/ui.lua", 51460, "src/ui.lua" },
  { "src/util.lua", 5452, "src/util.lua" }
}

local BUNDLE = { "dist/opencode.lua", 242358, "opencode.lua" }

-- Where the files land. Decided once, here, rather than relying on the shell's
-- directory still being the same when the last file arrives.
local DIR = shell.dir()

--- The terminal's width, or 51, which is what a Computer or Turtle gives you.
local function columns()
  local ok, width = pcall(function()
    return term.getSize()
  end)
  if ok and type(width) == "number" and width > 0 then
    return width
  end
  return 51
end

--- Print, wrapped to the terminal.
--
-- ComputerCraft's `print` does not wrap: a line wider than the terminal is
-- discarded past the right edge rather than continued on the next row. This
-- program has to say things like a base url and a size mismatch, both wider
-- than 51 columns, and the half of a line that carries the actual error is the
-- half that never arrives. Breaking at a space where there is one keeps a long
-- line readable rather than cutting it mid-word.
--
-- One column is left spare, for the same reason the library's screen adapter
-- leaves it: filling the last column is what makes what happens next depend on
-- the version, and this is the first thing anyone sees. It is a separate program
-- from the library, running before it exists, so it does its own wrapping and
-- cannot borrow the adapter's.
local function say(text)
  local width = math.max(8, columns() - 1)
  for paragraph in (tostring(text) .. "\n"):gmatch("([^\n]*)\n") do
    if paragraph == "" then
      print()
    else
      local rest = paragraph
      while #rest > width do
        -- `.*` is greedy, so this is the last space at or before the margin
        -- rather than the first.
        local space = rest:sub(1, width + 1):match("^.*()%s")
        local take
        if space and space >= math.floor(width / 2) then
          take = space - 1 -- stop before the space
        else
          take = width -- nothing to break on, so fill the line
        end
        print(rest:sub(1, take))
        rest = rest:sub(take + 1):gsub("^%s+", "")
      end
      print(rest)
    end
  end
end

-- Why the last attempt to find the raw files did not work, for the message the
-- failure path prints.
local DISCOVERY = ""

local function fail(message)
  say("install: " .. message)
  return 1
end

--- Create every missing directory along a path, which may be absolute.
local function mkdirs(path)
  -- An absolute path starts with "/" and must not lose it, and the leading
  -- segment is never missing, so the walk begins from an empty prefix.
  local prefix = path:sub(1, 1) == "/" and "" or nil
  for part in path:gmatch("[^/]+") do
    prefix = prefix == nil and part or (prefix .. "/" .. part)
    if not fs.exists(prefix) then
      fs.makeDir(prefix)
    end
  end
end

local function write(path, content)
  local directory = fs.getDir(path)
  if directory and directory ~= "" and directory ~= "." then
    mkdirs(directory)
  end
  local handle = fs.open(path, "w")
  if not handle then
    return false, "could not open " .. path .. " for writing"
  end
  handle.write(content)
  handle.close()
  return true
end

--- Fetch one url. A non-2xx status is an error rather than a body: a proxy or a
--- rate limit answers with a page, and writing that as a Lua file would break
--- the install in a way that is much harder to read than a refused download.
--
-- `http.request` throws rather than returning, and a host the server's allowlist
-- does not permit throws too. That one is worth catching by name: it is the
-- likeliest way for an install to fail, it is fixed in a config file rather than
-- anything reachable from here, and left alone it arrives as a Lua stack trace
-- through the middle of a download loop.
local function fetch(url)
  -- `http.get`, never `http.request`.
  --
  -- `http.request` is the asynchronous half of CC's api: it starts the request and
  -- returns immediately, delivering the response later as an `http_success` event.
  -- Its own source calls the return value "for legacy reasons" and undocumented.
  -- It is a boolean, so reading a response out of it raises "attempt to index
  -- local 'handle' (a boolean value)" on the very first file, before anything is
  -- written. `http.get` is the synchronous wrapper around that same call.
  --
  -- The url goes inside the table. CC dispatches on the type of the first
  -- argument, and a string puts it in the legacy positional signature, where
  -- argument 2 is the body and must be a string.
  --
  -- A failure comes back as `nil, message`, plus the failing response as a third
  -- value whenever the server answered at all. The size check needs the status
  -- from that third value, not the message, which on a computer is a bare reason
  -- phrase.
  local ok, handle, reason, failed = pcall(http.get, { url = url, timeout = 60 })
  if not ok then
    return nil, tostring(handle)
  end
  if not handle then
    if failed then
      local code = failed.getResponseCode and failed.getResponseCode() or 0
      if failed.close then
        failed.close()
      end
      return nil, "HTTP " .. code
    end
    -- The socket failed, and nothing answered. A host the server's allowlist does
    -- not permit lands here too, because CC refuses it before making the request.
    reason = tostring(reason or "could not connect")
    local lower = reason:lower()
    if lower:find("domain", 1, true) and lower:find("not permitted", 1, true) then
      local host = url:match("^https?://([^/]+)") or url
      return nil, "the server's http allowlist does not permit " .. host
    end
    return nil, reason
  end
  local status = handle.getResponseCode()
  local body = handle.readAll()
  handle.close()
  if status < 200 or status >= 300 then
    return nil, "HTTP " .. status
  end
  return body
end

--- Where a host might serve the raw files of a repository, most likely first.
--
-- Git does not say, and the answer is a property of the host rather than of the
-- repository, so the list is a guess that `discover` checks rather than a fact
-- baked in here.
local function candidates(repo, branch)
  local out, seen = {}, {}
  local function add(url)
    if url and not seen[url] then
      seen[url] = true
      out[#out + 1] = url
    end
  end
  -- GitHub does not serve raw files from the repository's own host, and it
  -- wants the owner and the name separately.
  local owner, name = repo:match("^https?://[^/]+/([^/]+)/([^/]+)$")
  if owner and name and repo:find("github%.com") then
    add(string.format("https://raw.githubusercontent.com/%s/%s/%s/", owner, name, branch))
  end
  add(repo .. "/raw/branch/" .. branch .. "/") -- Gitea, Forgejo, Gogs, Codeberg
  add(repo .. "/-/raw/" .. branch .. "/") -- GitLab
  add(repo .. "/raw/" .. branch .. "/") -- Bitbucket, older Gitea
  add(repo .. "/branch/" .. branch .. "/") -- a plain git http server
  return out
end

--- Whether any candidate after `from` is on a different host.
--
-- The allowlist refuses a host, not a path, so once a host is refused there is
-- nothing to learn from asking it again under a different shape. GitHub is the
-- exception worth keeping: its raw files live on a host of its own, so a
-- repository on github.com that is refused is still worth one try elsewhere.
local function reachesAnotherHost(list, from)
  local host = list[from]:match("^https?://([^/]+)")
  for index = from + 1, #list do
    if list[index]:match("^https?://([^/]+)") ~= host then
      return true
    end
  end
  return false
end

--- Find a base url that serves `path` at exactly `size` bytes.
--
-- Comparing sizes is what makes guessing safe. A web page answers 200 just as
-- readily as a file, and a login page answers 200 too; neither is 16 KB of Lua,
-- so both are rejected without ever being written anywhere. The file is
-- downloaded once more afterwards, which costs one request and keeps this free
-- of any state to carry around.
--
-- `repo` and `branch` are taken rather than read off the file's own locals because
--- this is called for two repositories: this one, and CC-GUI's.
--
-- The reason the last attempt failed is returned rather than printed, because the
-- two callers want different things from it: the main one has a long message about
-- allowlists and forks to put it in, and the CC-GUI one has a shorter one about an
-- optional dependency.
local function discover(repo, branch, path, size)
  if repo == "" then
    -- A reason rather than a nil, because the caller assigns what comes back into a
    -- variable it then prints: a nil there is a crash in the message about the
    -- failure, which is the one moment a program is allowed no other problem.
    return nil, "this installer has no repository to look in"
  end
  local list = candidates(repo, branch)
  local last
  for index, base in ipairs(list) do
    say("trying " .. base)
    local body, err = fetch(base .. path)
    if body and #body == size then
      say("found it")
      return base
    end
    last = err or ("got " .. #body .. " bytes, expected " .. size)
    if tostring(err):lower():find("allowlist", 1, true) and not reachesAnotherHost(list, index) then
      break
    end
  end
  return nil, tostring(last)
end

local function one(base, entry)
  local path, size, target = entry[1], entry[2], entry[3]
  local body, err = fetch(base .. path)
  if not body then
    return false, err
  end
  if #body ~= size then
    return false, string.format("got %d bytes, expected %d", #body, size)
  end
  return write(DIR .. "/" .. target, body)
end

local function run(argv)
  local base, bundle = BASE, false
  -- The repository this install comes from, as locals: `discover` takes them as
  -- arguments now that it is called for a second repository too, and a file-level
  -- local read through a parameter list is a local that is not there.
  local repo, branch = REPO, BRANCH
  for index = 1, #argv do
    local item = argv[index]
    if item == "--bundle" then
      bundle = true
    elseif item:find("^https?://") then
      base = item
    else
      return fail("unexpected argument '" .. item .. "'. Usage: install [--bundle] [url]")
    end
  end

  local list = bundle and { BUNDLE } or FILES
  if base == "" then
    -- Probe with the first file either way: it is the one every candidate has
    -- to serve, and its size is the only thing that can tell a file from a page.
    local probe = list[1]
    local found, reason = discover(repo, branch, probe[1], probe[2])
    if found then
      base = found
    else
      DISCOVERY = reason
      say("no candidate worked; the last said: " .. DISCOVERY)
      if DISCOVERY:find("allowlist", 1, true) then
        say("That is a server setting, not a network problem, and it is the")
        say("usual reason an install cannot get started. Add to")
        say("serverconfig/computercraft-server.toml, in the world folder:")
        print()
        say("  [[http.rules]]")
        say("  host = \"<the host>\"")
        say("  action = \"allow\"")
        say("  max_upload = 4194304")
        say("  max_download = 16777216")
        say("  timeout = 30000")
        print()
        say("then restart the server. If that host is on your own network, the")
        say("default $private deny rule refuses it by address first: remove the")
        say("[[http.rules]] entry with action = \"deny\" as well.")
        say("Alternatively, hand over a base url with:  install <base url>")
        return 2
      end
      say("Could not work out where to download this repository from.")
      if REPO == "" then
        say("This installer was built without a repository url, so it has")
        say("nowhere to look. Pass one, for example:")
        say("  install https://raw.githubusercontent.com/you/repo/main/")
      else
        say("The repository is " .. REPO .. ", branch " .. BRANCH .. ".")
        say("If it is private, or the host is not one of those above, pass the")
        say("url by hand:")
        say("  install <base url>")
      end
      return 2
    end
  end
  base = base:gsub("/+$", "") .. "/"
  say("installing " .. #list .. " file(s) from " .. base .. " into " .. DIR)
  local bytes, done = 0, 0
  for _, entry in ipairs(list) do
    local ok, err = one(base, entry)
    if not ok then
      -- Stop at the first failure. A wrong base url, a rate limit, or a dropped
      -- connection fails every remaining file the same way, so carrying on
      -- would spend twenty more requests to learn nothing, and would leave a
      -- half-written tree behind. Running `install` again is the fix, and it is
      -- safe: every file is simply written again.
      say(string.format("  FAIL  %-26s %s", entry[1], err))
      say(string.format("stopped at %d of %d file(s); %d were written to %s", done, #list, done, DIR))
      return 1
    end
    done = done + 1
    bytes = bytes + entry[2]
    say(string.format("  ok    %-26s %7d bytes", entry[1], entry[2]))
  end

  -- CC-GUI, which the interface is built on, fetched from its own repository and
  -- written beside the program so the bundle finds it too.
  --
  -- Optional, and that is the whole of the difference between this and the loop above.
  -- The program asks for it with a `pcall` and carries on without it, on the plain
  -- screen; nothing else in this install has that property. So a failure here is
  -- reported and the run goes on, and the program itself says why its screen is
  -- plainer -- an installer that refused to install the program because an optional
  -- dependency could not be fetched would leave a computer with nothing on it.
  local guiBase, guiReason = discover(GUI_REPO, GUI_BRANCH, GUI_PATH, GUI_SIZE)
  local guiOk = false
  if guiBase then
    guiBase = guiBase:gsub("/+$", "") .. "/"
    local body, err = fetch(guiBase .. GUI_PATH)
    if body and #body == GUI_SIZE then
      local written, writeErr = write(DIR .. "/" .. GUI_PATH, body)
      if written then
        guiOk = true
        bytes = bytes + GUI_SIZE
        say("  ok    GUI.lua")
      else
        say("  FAIL  GUI.lua")
        say("        " .. tostring(writeErr))
      end
    else
      say("  FAIL  GUI.lua")
      say("        " .. tostring(err or ("got " .. #body .. " bytes, expected " .. GUI_SIZE)))
    end
  end
  if not guiOk then
    say("the interface is unavailable without it: the program runs on the plain")
    say("screen, and says so the first time it starts. It can be fetched by hand:")
    say("  wget " .. GUI_REPO .. "/raw/branch/" .. GUI_BRANCH .. "/GUI.lua")
  end

  -- `./` is not decoration.
  -- `./` is not decoration. A ComputerCraft shell finds a program by name on the
  -- program path, which on a computer is `/rom/programs` -- a directory that is
  -- read-only, so nothing can be installed there and a bare name never resolves.
  -- A name containing a slash is resolved against the current directory instead,
  -- which is where these files were just written. So `./init.lua` works and
  -- `init.lua` need not, and `shell.run` needs the same `./` for the same reason:
  -- it goes through the same lookup.
  --
  -- `opencode init.lua` is what a shell on a desktop would take, and it is wrong
  -- twice over here: no such program is installed, and its argument would be read
  -- as a question to send the model.
  local program = bundle and "opencode.lua" or "init.lua"
  -- CC-GUI counts as a file when it arrived, because it did: it is written beside the
  -- program and the program finds it there. Not counting it would be a report that
  -- says less than was done.
  local installed = #list + (guiOk and 1 or 0)
  say(string.format("installed %d file(s), %d bytes, into %s", installed, bytes, DIR))
  say("run it with:  ./" .. program)
  say("or in Lua:    shell.run(\"./" .. program .. "\")")
  return 0
end

-- Returning, not `os.exit`: ComputerCraft has no `os.exit`, and a program ends
-- when it returns to the prompt. The return value is only read by the test
-- suite, which loads this file rather than running it on a computer.
return run(arg or {})
